describe('Payment Flow - Card Declined Error', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Adjust the URL to your payment page
    });

    it('should display an error message when the card is declined (happy path)', () => {
        cy.get('input[name="cardNumber"]').type('4000 0000 0000 0002'); // Example of a test card that simulates decline
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('be.visible').and('contain', 'Your card was declined. Please try another payment method.');
    });

    it('should not proceed with payment when card is declined (edge case)', () => {
        cy.get('input[name="cardNumber"]').type('4000 0000 0000 0002'); // Example of a test card that simulates decline
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.url().should('include', '/payment'); // Ensure we remain on the payment page
        cy.get('.error-message').should('be.visible');
        cy.get('button[type="confirm"]').should('not.exist'); // Confirm button should not be present
    });
});
